// 由 Common 提供，image pass 依赖它 —— 拼接失败会直接编译报错
vec2 deckSampleUv(float x) {
    if (x < 0.3333333) return vec2(0.125, 0.125);
    if (x < 0.6666667) return vec2(0.5, 0.5);
    return vec2(0.875, 0.875);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy;
    vec3 c = texture(iChannel0, deckSampleUv(uv.x)).rgb;
    fragColor = vec4(c, 1.0);
}
